CREATE DATABASE IF NOT EXISTS rentalin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE rentalin;
-- PERINGATAN: tabel lama dengan nama sama akan dihapus saat import.
SET FOREIGN_KEY_CHECKS=0; DROP TABLE IF EXISTS bookings; DROP TABLE IF EXISTS vehicles; DROP TABLE IF EXISTS password_resets; DROP TABLE IF EXISTS users; SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(30) NULL,email_verified_at TIMESTAMP NULL,password VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',remember_token VARCHAR(100) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE password_resets(email VARCHAR(150) NOT NULL,token VARCHAR(255) NOT NULL,created_at TIMESTAMP NULL,KEY password_resets_email_index(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,brand VARCHAR(100) NULL,type ENUM('motor','mobil') NOT NULL,year SMALLINT NULL,plate_number VARCHAR(20) NOT NULL UNIQUE,price_per_day DECIMAL(12,2) NOT NULL,description TEXT NULL,image VARCHAR(500) NULL,status ENUM('available','unavailable') NOT NULL DEFAULT 'available',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bookings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,total_days INT UNSIGNED NOT NULL,total_price DECIMAL(12,2) NOT NULL,status ENUM('pending','approved','rejected','completed','cancelled') NOT NULL DEFAULT 'pending',notes VARCHAR(500) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT,INDEX(vehicle_id,start_date,end_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
